const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let idx = 0;
const A = data[idx++];
const L = data[idx++];
const N = data[idx++];

const photoMin = Math.min(A, L);
const photoMax = Math.max(A, L);
const photoArea = A * L;

let bestId = -1;
let bestUnused = Infinity;

for (let i = 1; i <= N; i++) {
    const X = data[idx++];
    const Y = data[idx++];

    const frameMin = Math.min(X, Y);
    const frameMax = Math.max(X, Y);

    if (frameMin >= photoMin && frameMax >= photoMax) {
        const unused = X * Y - photoArea;
        if (unused < bestUnused) {
            bestUnused = unused;
            bestId = i;
        }
    }
}

console.log(bestId);
